from collections import deque


class Solution:
    def distanceK(self, root: 'TreeNode', target: 'TreeNode', k: int) -> list[int]:
        parent = {root: None}
        stack = [root]
        while stack:                              # record every node's parent: O(n)
            node = stack.pop()
            for child in (node.left, node.right):
                if child:
                    parent[child] = node
                    stack.append(child)
        queue = deque([target])
        seen = {target}
        for _ in range(k):                        # expand k BFS levels
            for _ in range(len(queue)):
                node = queue.popleft()
                for nxt in (node.left, node.right, parent[node]):   # up as well as down
                    if nxt and nxt not in seen:
                        seen.add(nxt)
                        queue.append(nxt)
        return [node.val for node in queue]       # exactly the nodes at distance k
